# ---------------------------------------------------------------- S11
S(11, 'Form W-4, withholding, and Form W-2', 'Explain how Form W-4 sets withholding and what Form W-2 reports',
  main=[
    q('Kayla starts her first job. Her employer asks her to fill out Form W-4. What is it used for?', 'To set her federal income tax withholding',
      [('To apply for a Social Security number', 'Confuses the W-4 with an SSN application'), ('To report her yearly wages to the IRS', 'Confuses the W-4 with the W-2'), ('To sign up for health insurance', 'Confuses tax forms with benefit forms')],
      intro='Form W-4 (Employee\'s Withholding Certificate) tells your employer how much federal income tax to withhold from each paycheck. You fill it out when you start a job and can update it any time, such as after a second job begins or your situation changes.',
      fb='The W-4 sets federal income tax withholding.', sub='Purpose of W-4', how=True),
    q('Where does Kayla send her completed Form W-4?', 'To her employer',
      [('To the IRS by mail', 'Thinks the W-4 goes to the IRS'), ('To her bank', 'Confuses payroll with banking'), ('To her state\'s motor vehicle agency', 'Unrelated agency')],
      intro='You give Form W-4 to your employer, not the IRS. The employer\'s payroll system uses it to calculate withholding.',
      fb='The employer keeps the W-4 and uses it for payroll.', sub='Filing the W-4', how=True),
    q('On her W-4, Kayla asks for $20 of extra withholding per paycheck. She is paid biweekly. How much extra will be withheld over a full year?', '$520',
      [('$240', 'Uses 12 paychecks'), ('$480', 'Uses 24 paychecks'), ('$1,040', 'Uses 52 paychecks')],
      intro='Step 4(c) of Form W-4 lets you request extra withholding each pay period. Multiply by the number of paychecks in a year to see the yearly effect.',
      fb='Biweekly = 26 paychecks: $20 × 26 = $520.', calc=20 * 26, sub='Extra withholding'),
    q('It is February 15, and Ana still has not received last year\'s Form W-2 from her employer. What is true?', 'It is late; she should contact the employer',
      [('It is on time; W-2s are due by April 15', 'Confuses the W-2 deadline with the tax filing deadline'), ('It is on time; W-2s are due by June 30', 'Invents a mid-year date'), ('She should skip filing this year without it', 'Ignores that she can request it and still file')],
      intro='Form W-2 (Wage and Tax Statement) reports a worker\'s wages for the year and the taxes withheld. Employers must send it by January 31, and employees use it to file their tax returns.',
      fb='W-2s are due by January 31, so a missing W-2 in mid-February is late; ask the employer, and the IRS can help if it still does not arrive.', sub='W-2 deadline', eff='IRS deadline as of 2026', how=True),
    q('Which statement about income tax withholding is TRUE?', 'It prepays the year\'s tax',
      [('It is an extra tax on top of what is owed', 'Thinks withholding adds tax'), ('It is money the employer keeps', 'Thinks employers keep withheld tax'), ('It is optional for every employee', 'Ignores withholding requirements')],
      fb='Withholding pays your tax in advance. When you file, it is compared with your actual tax: overpaying gives a refund; underpaying means a balance due.', sub='Withholding'),
  ],
  back=[
    concept('Why taxes are withheld from pay', 'Understanding withholding as pay-as-you-go tax payment explains what the W-4 and W-2 do.', [
      q('The U.S. income tax is "pay-as-you-go." What does this mean for employees?', 'Tax is paid gradually through paycheck withholding during the year',
        [('Tax is paid once, only when you retire', 'Thinks tax waits until retirement'), ('Only people who ask to pay tax have to pay it', 'Thinks tax is voluntary'), ('Tax is paid only by employers, never employees', 'Confuses employer and employee taxes')],
        intro='Federal income tax is collected throughout the year. For employees, the employer withholds part of each paycheck and sends it to the government on the employee\'s behalf.',
        fb='Withholding spreads tax payments over the year.', sub='Pay-as-you-go'),
      q('Who sends the withheld tax to the government?', 'The employer',
        [('The employee mails cash each week', 'Thinks employees pay directly'), ('The employee\'s bank', 'Confuses banks with payroll'), ('Nobody until tax filing day', 'Thinks withholding is held until filing')],
        intro='Withholding means the tax is taken out of a paycheck before the worker receives it.',
        fb='Employers deposit withheld taxes with the government.', sub='Who remits'),
      q('If too much tax is withheld during the year, what happens after filing a tax return?', 'The extra is returned as a refund',
        [('The extra is lost', 'Thinks overpayment is kept by the government'), ('The extra is added to next year\'s salary', 'Confuses refunds with pay'), ('The employer pays the employee a bonus', 'Confuses refunds with bonuses')],
        intro='When you file a tax return, you calculate your actual tax for the year and compare it with what was withheld.',
        fb='Overpaid tax is refunded after you file.', sub='Refunds'),
      q('If too little tax is withheld, what happens?', 'The employee owes the rest when filing',
        [('The government forgives the difference', 'Thinks underpayment is forgiven'), ('The employer pays the difference', 'Shifts the debt to the employer'), ('Nothing, because withholding is final', 'Thinks withholding settles all tax')],
        fb='Underpaid tax is owed with the return, sometimes with a penalty if the shortfall is large.', sub='Balance due'),
      q('Which document tells the employer how much to withhold?', 'Form W-4',
        [('Form W-2', 'The W-2 reports what was withheld'), ('A pay stub', 'The stub shows withholding but does not set it'), ('Form 1040', 'Confuses the tax return with the withholding form')],
        fb='The W-4 sets withholding; the W-2 reports it after the year ends.', sub='W-4 vs W-2'),
    ]),
    math('Solve real-world problems with decimal operations', 'Yearly withholding totals multiply per-paycheck amounts by the number of pay periods.', 'grade_5', 22),
  ],
  go=[
    deeper('Getting withholding about right', [
      q('Last year Kayla received a $1,300 refund. What does that tell her?', 'She had $1,300 more withheld than her tax',
        [('She earned a $1,300 bonus from the IRS', 'Treats a refund as free money'), ('Her employer underpaid her by $1,300', 'Confuses withholding with wages'), ('She owes $1,300 more next year', 'Reverses the meaning')],
        intro='A tax refund is your own overpaid tax coming back. It is not extra income. A large refund means you could have had more in each paycheck during the year.',
        fb='A refund is a return of overpaid tax, not a bonus.', sub='Meaning of a refund'),
      q('Kayla\'s $1,300 tax refund came from tax withheld beyond what she owed. If that amount had stayed in her 26 biweekly paychecks instead, about how much more would each paycheck have been?', '$50',
        [('$108.33', 'Uses 12 paychecks'), ('$25', 'Uses 52 paychecks'), ('$1,300', 'Gives the yearly total')],
        fb='$1,300 ÷ 26 = $50 per paycheck.', calc=1300 / 26, sub='Refund per paycheck'),
      q('Which free tool helps workers check whether their withholding is about right?', 'The IRS Tax Withholding Estimator',
        [('A credit score app that tracks her accounts', 'Confuses tax withholding with credit monitoring'), ('Her W-2 from last year, without any changes', 'Assumes last year\'s withholding still fits this year'), ('A social media poll of coworkers', 'Unreliable source')],
        intro='The IRS offers a free online Tax Withholding Estimator. Using recent pay stubs, it suggests how to fill out a new W-4 to get closer to the right amount.',
        fb='The IRS estimator uses your pay information to suggest W-4 changes.', sub='Estimator', how=True),
      q('Kayla starts a second part-time job. Why might her withholding now be too low?', 'Each employer withholds as if that job were her only income',
        [('Two jobs always get the correct combined withholding automatically', 'Thinks withholding adds up correctly automatically'), ('Part-time jobs are not taxed', 'Invents an exemption'), ('Her first employer stops withholding', 'Invents a rule')],
        intro='When you have more than one job, each employer\'s payroll may assume its pay is your only income, so total withholding can fall short. Step 2 of Form W-4 addresses multiple jobs.',
        fb='Each payroll ignores the other job, so combined income can be under-withheld. Updating the W-4 (Step 2) fixes this.', sub='Multiple jobs'),
      q('Kayla expects to owe $200 more than will be withheld this year. She has 10 paychecks left. How much extra per paycheck should she request?', '$20',
        [('$200', 'Puts the whole amount on one paycheck'), ('$10', 'Uses 20 paychecks'), ('$2', 'Uses 100 paychecks')],
        fb='$200 ÷ 10 = $20 per paycheck.', calc=200 / 10, sub='Adjusting mid-year'),
    ]),
    deeper('Claiming exemption from withholding', [
      q('Under IRS rules, who may claim exemption from federal income tax withholding on Form W-4?', 'Someone who owed no tax last year and expects none this year',
        [('Anyone under age 21', 'Invents an age rule'), ('Anyone who works part time while attending high school', 'Invents a part-time rule'), ('Anyone who wants a larger paycheck', 'Treats exemption as a choice')],
        intro='You may claim "exempt" on Form W-4 only if you had no federal income tax liability last year and expect none this year. Exemption affects federal income tax withholding only, not Social Security or Medicare.',
        fb='Both conditions must be met: no liability last year and none expected this year.', sub='Exempt status', eff='IRS Form W-4 rules as of 2026'),
      q('A student claims exempt on Form W-4, so no federal income tax is withheld, but earns enough to owe tax. What is the likely result?', 'A tax bill when filing, and possibly a penalty',
        [('No tax is ever owed', 'Thinks exempt status erases tax'), ('The employer pays the tax', 'Shifts the tax to the employer'), ('A larger refund when filing next spring', 'Reverses the effect')],
        fb='Exempt status stops withholding, not tax. Tax still owed is due with the return.', sub='Risk of claiming exempt'),
      q('If a worker claims exempt from federal income tax withholding on Form W-4, which taxes are still withheld?', 'Social Security and Medicare',
        [('Federal income tax only', 'Reverses the rule'), ('No taxes at all', 'Overstates exemption'), ('Only sales tax', 'Confuses payroll with sales tax')],
        fb='Exempt status applies only to federal income tax withholding; FICA still applies.', sub='What exempt covers'),
      q('How long does a claim of exemption on Form W-4 last?', 'One year; a new W-4 is needed to continue it',
        [('Forever, once claimed', 'Thinks exemption is permanent'), ('Until the worker turns 18', 'Invents an age limit'), ('Five years', 'Invents a period')],
        intro='A claim of exemption from withholding expires and must be renewed with a new Form W-4 each year.',
        fb='Exemption must be renewed each year.', sub='Renewal'),
      q('IRS rules allow claiming exempt only with no income tax liability last year and none expected this year. Jamal earned $3,000 last year and owed no federal income tax. This year he expects to earn $28,000 at a full-time job. Should he claim exempt?', 'No; he expects to owe income tax this year',
        [('Yes, because he owed nothing last year', 'Uses only one of the two conditions'), ('Yes, because he is a new worker', 'Invents a rule'), ('Yes, so that he can get a bigger refund next spring', 'Misunderstands the effect')],
        fb='Both conditions must hold. At $28,000 he would expect to owe tax, so exemption is not allowed.', sub='Applying the rule'),
    ]),
  ],
  nat=('Earning Income', '12-6a calculate taxes likely withheld; tax forms used by employees'), nj=['EG', 'PB'],
  status='time_sensitive', sources=[W4, W2], extra=['Filling out Form W-4', 'Using the IRS Tax Withholding Estimator'])
